SELECT 'PUBLIC215_NUMERIC_IMPLEMENTATIONS'AS marker,public.fn_gto_v31_public215_physics_implementation()AS physics,public.fn_gto_v31_public215_encoding_implementation()AS encoding;
SELECT 'PUBLIC215_FUNCTION_IDENTITY'AS marker,oid::regprocedure::text AS signature,md5(pg_get_functiondef(oid))AS source_md5 FROM pg_proc WHERE oid IN('public.fn_gto_v31_prepare_model(uuid,jsonb)'::regprocedure,'public.fn_gto_v31_freeze_model(uuid,jsonb)'::regprocedure,'public.fn_gto_v31_model_freeze_authority(uuid)'::regprocedure,'public.fn_gto_v31_ingest_source_artifact(uuid,text,jsonb)'::regprocedure,'public.fn_gto_v31_build_cell(uuid,jsonb)'::regprocedure,'public.fn_gto_v31_heldout_metrics(uuid,text)'::regprocedure,'public.fn_horse_solver_agreement_v31_decision(jsonb)'::regprocedure,'public.fn_gto_v31_active_cells(integer,integer)'::regprocedure,'public.fn_gto_v31_evaluation_cells(uuid,integer,integer)'::regprocedure,'public.fn_gto_v31_cell_payload_checksum(jsonb)'::regprocedure,'public.fn_gto_v31_cell_payload_valid(jsonb)'::regprocedure,'public.fn_gto_v31_public215_frozen_map(public.gto_v31_datasets)'::regprocedure,'public.fn_gto_v31_public215_provenance_valid(public.gto_v31_runtime_cells,public.gto_v31_datasets,public.gto_v31_input_bundles,jsonb)'::regprocedure,'public.fn_gto_v31_public215_source_headers_valid(public.gto_v31_datasets)'::regprocedure,'public.ca_gto_v31_approve_input_bundle(jsonb)'::regprocedure,'public.fn_gto_v31_register_dataset(jsonb)'::regprocedure)ORDER BY signature;
